content:
:root {
  --bg-color: #0f172a;
  --panel-bg: #1e293b;
  --text-color: #f8fafc;
  --text-muted: #94a3b8;
  --white-key-bg: #ffffff;
  --white-key-hover: #f1f5f9;
  --white-key-active: #e2e8f0;
  --black-key-bg: #0f172a;
  --black-key-hover: #334155;
  --black-key-active: #475569;
  --accent-color: #3b82f6;
  --accent-hover: #2563eb;
  --border-color: #334155;
  --shadow-color: rgba(0, 0, 0, 0.3);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  background-color: var(--bg-color);
  color: var(--text-color);
  min-height: 100vh;
  display: flex;
  justify-content: center;
  align-items: center;
  padding: 20px;
}

.app-container {
  background-color: var(--panel-bg);
  border: 1px solid var(--border-color);
  border-radius: 16px;
  padding: 30px;
  width: 100%;
  max-width: 800px;
  box-shadow: 0 10px 25px var(--shadow-color);
  display: flex;
  flex-direction: column;
  gap: 24px;
}

.piano-title {
  font-size: 1.8rem;
  font-weight: 700;
  text-align: center;
  color: var(--text-color);
  letter-spacing: -0.025em;
}

.piano-subtitle {
  font-size: 0.95rem;
  text-align: center;
  color: var(--text-muted);
  margin-top: -16px;
}

.piano-body {
  display: flex;
  flex-direction: column;
  gap: 20px;
  background: rgba(15, 23, 42, 0.4);
  padding: 24px;
  border-radius: 12px;
  border: 1px solid var(--border-color);
}

.controls {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 16px;
  padding-bottom: 12px;
  border-bottom: 1px solid var(--border-color);
}

.controls label {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 0.9rem;
  color: var(--text-muted);
}

.controls input[type="range"] {
  accent-color: var(--accent-color);
  cursor: pointer;
}

.btn {
  background-color: var(--accent-color);
  color: white;
  border: none;
  padding: 8px 16px;
  border-radius: 8px;
  font-size: 0.9rem;
  font-weight: 600;
  cursor: pointer;
  transition: background-color 0.2s, transform 0.1s;
}

.btn:hover {
  background-color: var(--accent-hover);
}

.btn:active {
  transform: scale(0.97);
}

.keyboard {
  position: relative;
  display: flex;
  height: 220px;
  background-color: #090d16;
  border-radius: 8px;
  overflow: hidden;
  box-shadow: inset 0 4px 6px rgba(0, 0, 0, 0.4);
  justify-content: center;
  padding: 10px;
}

.key {
  position: relative;
  cursor: pointer;
  user-select: none;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  align-items: center;
  padding-bottom: 12px;
  transition: background-color 0.1s, transform 0.05s;
}

.white-key {
  background-color: var(--white-key-bg);
  color: #1e293b;
  width: 52px;
  height: 200px;
  border: 1px solid #cbd5e1;
  border-radius: 0 0 6px 6px;
  z-index: 1;
}

.white-key:hover {
  background-color: var(--white-key-hover);
}

.white-key.active {
  background-color: var(--white-key-active);
  transform: translateY(2px);
  box-shadow: inset 0 2px 4px rgba(0, 0, 0, 0.2);
}

.black-key {
  background-color: var(--black-key-bg);
  color: #f8fafc;
  width: 34px;
  height: 120px;
  border-radius: 0 0 4px 4px;
  position: absolute;
  z-index: 2;
  border: 1px solid #1e293b;
  box-shadow: 0 4px 6px rgba(0, 0, 0, 0.3);
}

.black-key:hover {
  background-color: var(--black-key-hover);
}

.black-key.active {
  background-color: var(--black-key-active);
  height: 118px;
  transform: translateY(2px);
}

.key-label {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
  font-size: 0.75rem;
  font-weight: 600;
}

.key-label span:last-child {
  font-size: 0.65rem;
  opacity: 0.7;
}

.history-section {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.history-section h3 {
  font-size: 1rem;
  font-weight: 600;
  color: var(--text-muted);
}

.history-list {
  display: flex;
  gap: 8px;
  overflow-x: auto;
  padding-bottom: 8px;
  min-height: 44px;
  align-items: center;
}

.history-list::-webkit-scrollbar {
  height: 6px;
}

.history-list::-webkit-scrollbar-thumb {
  background-color: var(--border-color);
  border-radius: 3px;
}

.history-item {
  background-color: rgba(59, 130, 246, 0.15);
  border: 1px solid rgba(59, 130, 246, 0.3);
  padding: 6px 12px;
  border-radius: 6px;
  font-size: 0.85rem;
  display: flex;
  gap: 8px;
  align-items: center;
  white-space: nowrap;
  animation: fadeIn 0.2s ease-out;
}

.history-item span:last-child {
  color: var(--text-muted);
  font-size: 0.75rem;
}

@keyframes fadeIn {
  from {
    opacity: 0;
    transform: translateY(4px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@media (max-width: 768px) {
  .app-container {
    padding: 16px;
  }
  .keyboard {
    height: 180px;
    padding: 5px;
  }
  .white-key {
    width: 38px;
    height: 160px;
  }
  .black-key {
    width: 24px;
    height: 95px;
  }
}

export interface Note {
  id: string;
  name: string;
  frequency: number;
  isBlack: boolean;
  keyboardKey: string;
}

export interface HistoryItem {
  id: string;
  noteName: string;
  time: string;
}

import { useState, useEffect, useCallback, useRef } from 'react';
import { Note, HistoryItem } from './types';

const NOTES: Note[] = [
  { id: 'C4', name: 'C4', frequency: 261.63, isBlack: false, keyboardKey: 'a' },
  { id: 'Db4', name: 'C#4', frequency: 277.18, isBlack: true, keyboardKey: 'w' },
  { id: 'D4', name: 'D4', frequency: 293.66, isBlack: false, keyboardKey: 's' },
  { id: 'Eb4', name: 'D#4', frequency: 311.13, isBlack: true, keyboardKey: 'e' },
  { id: 'E4', name: 'E4', frequency: 329.63, isBlack: false, keyboardKey: 'd' },
  { id: 'F4', name: 'F4', frequency: 349.23, isBlack: false, keyboardKey: 'f' },
  { id: 'Gb4', name: 'F#4', frequency: 369.99, isBlack: true, keyboardKey: 't' },
  { id: 'G4', name: 'G4', frequency: 392.00, isBlack: false, keyboardKey: 'g' },
  { id: 'Ab4', name: 'G#4', frequency: 415.30, isBlack: true, keyboardKey: 'y' },
  { id: 'A4', name: 'A4', frequency: 440.00, isBlack: false, keyboardKey: 'h' },
  { id: 'Bb4', name: 'A#4', frequency: 466.16, isBlack: true, keyboardKey: 'u' },
  { id: 'B4', name: 'B4', frequency: 493.88, isBlack: false, keyboardKey: 'j' },
  { id: 'C5', name: 'C5', frequency: 523.25, isBlack: false, keyboardKey: 'k' },
];

export default function App() {
  const [volume, setVolume] = useState<number>(0.3);
  const [activeKeys, setActiveKeys] = useState<Record<string, boolean>>({});
  const [history, setHistory] = useState<HistoryItem[]>([]);

  const audioCtxRef = useRef<AudioContext | null>(null);

  const getAudioContext = () => {
    if (!audioCtxRef.current) {
      const AudioContextClass = window.AudioContext || (window as unknown as { webkitAudioContext: typeof AudioContext }).webkitAudioContext;
      audioCtxRef.current = new AudioContextClass();
    }
    if (audioCtxRef.current.state === 'suspended') {
      audioCtxRef.current.resume();
    }
    return audioCtxRef.current;
  };

  const playNote = useCallback((note: Note) => {
    try {
      const ctx = getAudioContext();
      const osc = ctx.createOscillator();
      const gainNode = ctx.createGain();

      osc.type = 'sine';
      osc.frequency.setValueAtTime(note.frequency, ctx.currentTime);

      gainNode.gain.setValueAtTime(volume, ctx.currentTime);
      gainNode.gain.exponentialRampToValueAtTime(0.0001, ctx.currentTime + 0.8);

      osc.connect(gainNode);
      gainNode.connect(ctx.destination);

      osc.start();
      osc.stop(ctx.currentTime + 0.8);

      setActiveKeys((prev) => ({ ...prev, [note.id]: true }));
      setTimeout(() => {
        setActiveKeys((prev) => ({ ...prev, [note.id]: false }));
      }, 200);

      const now = new Date();
      const timeStr = now.toLocaleTimeString();
      const newItem: HistoryItem = {
        id: Math.random().toString(36).substring(2, 9),
        noteName: note.name,
        time: timeStr,
      };

      setHistory((prev) => [newItem, ...prev.slice(0, 19)]);
    } catch {
      // AudioContext policy errors handled gracefully
    }
  }, [volume]);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.repeat) return;
      const targetNote = NOTES.find((n) => n.keyboardKey === e.key.toLowerCase());
      if (targetNote) {
        playNote(targetNote);
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
    };
  }, [playNote]);

  const clearHistory = () => {
    setHistory([]);
  };

  return (
    <div className="app-container">
      <h1 className="piano-title">Web ピアノ</h1>
      <p className="piano-subtitle">1オクターブのWeb Audio API対応ピアノ</p>

      <div className="piano-body">
        <div className="controls">
          <label>
            ボリューム:
            <input
              type="range"
              min="0"
              max="1"
              step="0.01"
              value={volume}
              onChange={(e) => setVolume(parseFloat(e.target.value))}
            />
          </label>
          <button className="btn" onClick={clearHistory}>
            履歴をクリア
          </button>
        </div>

        <div className="keyboard">
          {NOTES.map((note) => {
            const isActive = activeKeys[note.id];
            const keyClass = note.isBlack ? 'black-key' : 'white-key';
            const activeClass = isActive ? 'active' : '';

            return (
              <div
                key={note.id}
                className={`key ${keyClass} ${activeClass}`}
                onMouseDown={() => playNote(note)}
              >
                <div className="key-label">
                  <span>{note.name}</span>
                  <span>{note.keyboardKey.toUpperCase()}</span>
                </div>
              </div>
            );
          })}
        </div>

        <div className="history-section">
          <h3>再生履歴</h3>
          <div className="history-list">
            {history.length === 0 ? (
              <span style={{ color: 'var(--text-muted)', fontSize: '0.85rem' }}>
                鍵盤を押すと履歴がここに表示されます
              </span>
            ) : (
              history.map((item) => (
                <div key={item.id} className="history-item">
                  <span>{item.noteName}</span>
                  <span>{item.time}</span>
                </div>
              ))
            )}
          </div>
        </div>
      </div>
    </div>
  );
}
